-- Catálogo BNCC-2018 de Matemática do Ensino Médio. Importação aditiva.
-- Fonte: https://api.bncc.dev/v1/habilidades?etapa=EM&area=em-area-mat&limite=100
-- Proveniência e localizadores MEC preservados em source_metadata.
INSERT INTO curriculum_areas(curriculum_version,source_key,name,stage) VALUES('BNCC-2018','em-area-mat','Matemática e suas Tecnologias','Ensino Médio') ON CONFLICT DO NOTHING;
WITH competencies(number,source_key,description) AS (VALUES
(1,'em-area-mat-ce-01','Utilizar estratégias, conceitos e procedimentos matemáticos para interpretar situações em diversos contextos, sejam atividades cotidianas, sejam fatos das Ciências da Natureza e Humanas, das questões socioeconômicas ou tecnológicas, divulgados por diferentes meios, de modo a contribuir para uma formação geral.'),
(2,'em-area-mat-ce-02','Propor ou participar de ações para investigar desafios do mundo contemporâneo e tomar decisões éticas e socialmente responsáveis, com base na análise de problemas sociais, como os voltados a situações de saúde, sustentabilidade, das implicações da tecnologia no mundo do trabalho, entre outros, mobilizando e articulando conceitos, procedimentos e linguagens próprios da Matemática.'),
(3,'em-area-mat-ce-03','Utilizar estratégias, conceitos, definições e procedimentos matemáticos para interpretar, construir modelos e resolver problemas em diversos contextos, analisando a plausibilidade dos resultados e a adequação das soluções propostas, de modo a construir argumentação consistente.'),
(4,'em-area-mat-ce-04','Compreender e utilizar, com flexibilidade e precisão, diferentes registros de representação matemáticos (algébrico, geométrico, estatístico, computacional etc.), na busca de solução e comunicação de resultados de problemas.'),
(5,'em-area-mat-ce-05','Investigar e estabelecer conjecturas a respeito de diferentes conceitos e propriedades matemáticas, empregando estratégias e recursos, como observação de padrões, experimentações e diferentes tecnologias, identificando a necessidade, ou não, de uma demonstração cada vez mais formal na validação das referidas conjecturas.')
) INSERT INTO curriculum_competencies(area_id,number,source_key,description,source_metadata) SELECT a.id,c.number,c.source_key,c.description,'{"documento":"bncc-2018","fonte":"api.bncc.dev"}'::jsonb FROM competencies c CROSS JOIN curriculum_areas a WHERE a.curriculum_version='BNCC-2018' AND a.source_key='em-area-mat' ON CONFLICT DO NOTHING;
INSERT INTO curriculum_skills(curriculum_version,code,stage,subject,grade_range,description,source_metadata) VALUES
('BNCC-2018','EM13MAT101','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Interpretar criticamente situações econômicas, sociais e fatos relativos às Ciências da Natureza que envolvam a variação de grandezas, pela análise dos gráficos das funções representadas e das taxas de variação, com ou sem apoio de tecnologias digitais.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 3", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 535"}'::jsonb),
('BNCC-2018','EM13MAT102','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Analisar tabelas, gráficos e amostras de pesquisas estatísticas apresentadas em relatórios divulgados por diferentes meios de comunicação, identificando, quando for o caso, inadequações que possam induzir a erros de interpretação, como escalas e amostras não apropriadas.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 4", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 535"}'::jsonb),
('BNCC-2018','EM13MAT103','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Interpretar e compreender textos científicos ou divulgados pelas mídias, que empregam unidades de medida de diferentes grandezas e as conversões possíveis entre elas, adotadas ou não pelo Sistema Internacional (SI), como as de armazenamento e velocidade de transferência de dados, ligadas aos avanços tecnológicos.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 5", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 535"}'::jsonb),
('BNCC-2018','EM13MAT104','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Interpretar taxas e índices de natureza socioeconômica (índice de desenvolvimento humano, taxas de inflação, entre outros), investigando os processos de cálculo desses números, para analisar criticamente a realidade e produzir argumentos.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 6", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 535"}'::jsonb),
('BNCC-2018','EM13MAT105','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Utilizar as noções de transformações isométricas (translação, reflexão, rotação e composições destas) e transformações homotéticas para construir figuras e analisar elementos da natureza e diferentes produções humanas (fractais, construções civis, obras de arte, entre outras).','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 7", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 535"}'::jsonb),
('BNCC-2018','EM13MAT106','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Identificar situações da vida cotidiana nas quais seja necessário fazer escolhas levando-se em conta os riscos probabilísticos (usar este ou aquele método contraceptivo, optar por um tratamento médico em detrimento de outro etc.).','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 8", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 535"}'::jsonb),
('BNCC-2018','EM13MAT201','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Propor ou participar de ações adequadas às demandas da região, preferencialmente para sua comunidade, envolvendo medições e cálculos de perímetro, de área, de volume, de capacidade ou de massa.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 9", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 536"}'::jsonb),
('BNCC-2018','EM13MAT202','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Planejar e executar pesquisa amostral sobre questões relevantes, usando dados coletados diretamente ou em diferentes fontes, e comunicar os resultados por meio de relatório contendo gráficos e interpretação das medidas de tendência central e das medidas de dispersão (amplitude e desvio padrão), utilizando ou não recursos tecnológicos.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 10", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 536"}'::jsonb),
('BNCC-2018','EM13MAT203','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Aplicar conceitos matemáticos no planejamento, na execução e na análise de ações envolvendo a utilização de aplicativos e a criação de planilhas (para o controle de orçamento familiar, simuladores de cálculos de juros simples e compostos, entre outros), para tomar decisões.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 11", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 536"}'::jsonb),
('BNCC-2018','EM13MAT301','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Resolver e elaborar problemas do cotidiano, da Matemática e de outras áreas do conhecimento, que envolvem equações lineares simultâneas, usando técnicas algébricas e gráficas, com ou sem apoio de tecnologias digitais.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 12", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 538"}'::jsonb),
('BNCC-2018','EM13MAT302','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Construir modelos empregando as funções polinomiais de 1º ou 2º graus, para resolver problemas em contextos diversos, com ou sem apoio de tecnologias digitais.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 13", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 538"}'::jsonb),
('BNCC-2018','EM13MAT303','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Interpretar e comparar situações que envolvam juros simples com as que envolvem juros compostos, por meio de representações gráficas ou análise de planilhas, destacando o crescimento linear ou exponencial de cada caso.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 14", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 538"}'::jsonb),
('BNCC-2018','EM13MAT304','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Resolver e elaborar problemas com funções exponenciais nos quais seja necessário compreender e interpretar a variação das grandezas envolvidas, em contextos como o da Matemática Financeira, entre outros.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 15", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 538"}'::jsonb),
('BNCC-2018','EM13MAT305','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Resolver e elaborar problemas com funções logarítmicas nos quais seja necessário compreender e interpretar a variação das grandezas envolvidas, em contextos como os de abalos sísmicos, pH, radioatividade, Matemática Financeira, entre outros.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 16", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 538"}'::jsonb),
('BNCC-2018','EM13MAT306','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Resolver e elaborar problemas em contextos que envolvem fenômenos periódicos reais (ondas sonoras, fases da lua, movimentos cíclicos, entre outros) e comparar suas representações com as funções seno e cosseno, no plano cartesiano, com ou sem apoio de aplicativos de álgebra e geometria.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 17", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 538"}'::jsonb),
('BNCC-2018','EM13MAT307','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Empregar diferentes métodos para a obtenção da medida da área de uma superfície (reconfigurações, aproximação por cortes etc.) e deduzir expressões de cálculo para aplicá-las em situações reais (como o remanejamento e a distribuição de plantações, entre outros), com ou sem apoio de tecnologias digitais.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 18", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 538"}'::jsonb),
('BNCC-2018','EM13MAT308','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Aplicar as relações métricas, incluindo as leis do seno e do cosseno ou as noções de congruência e semelhança, para resolver e elaborar problemas que envolvem triângulos, em variados contextos.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 19", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 538"}'::jsonb),
('BNCC-2018','EM13MAT309','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Resolver e elaborar problemas que envolvem o cálculo de áreas totais e de volumes de prismas, pirâmides e corpos redondos em situações reais (como o cálculo do gasto de material para revestimento ou pinturas de objetos cujos formatos sejam composições dos sólidos estudados), com ou sem apoio de tecnologias digitais.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 20", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 539"}'::jsonb),
('BNCC-2018','EM13MAT310','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Resolver e elaborar problemas de contagem envolvendo agrupamentos ordenáveis ou não de elementos, por meio dos princípios multiplicativo e aditivo, recorrendo a estratégias diversas, como o diagrama de árvore.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 21", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 539"}'::jsonb),
('BNCC-2018','EM13MAT311','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Identificar e descrever o espaço amostral de eventos aleatórios, realizando contagem das possibilidades, para resolver e elaborar problemas que envolvem o cálculo da probabilidade.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 22", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 539"}'::jsonb),
('BNCC-2018','EM13MAT312','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Resolver e elaborar problemas que envolvem o cálculo de probabilidade de eventos em experimentos aleatórios sucessivos.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 23", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 539"}'::jsonb),
('BNCC-2018','EM13MAT313','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Utilizar, quando necessário, a notação científica para expressar uma medida, compreendendo as noções de algarismos significativos e algarismos duvidosos, e reconhecendo que toda medida é inevitavelmente acompanhada de erro.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 24", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 539"}'::jsonb),
('BNCC-2018','EM13MAT314','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Resolver e elaborar problemas que envolvem grandezas determinadas pela razão ou pelo produto de outras (velocidade, densidade demográfica, energia elétrica etc.).','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 25", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 539"}'::jsonb),
('BNCC-2018','EM13MAT315','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Investigar e registrar, por meio de um fluxograma, quando possível, um algoritmo que resolve um problema.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 26", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 539"}'::jsonb),
('BNCC-2018','EM13MAT316','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Resolver e elaborar problemas, em diferentes contextos, que envolvem cálculo e interpretação das medidas de tendência central (média, moda, mediana) e das medidas de dispersão (amplitude, variância e desvio padrão).','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 27", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 539"}'::jsonb),
('BNCC-2018','EM13MAT401','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Converter representações algébricas de funções polinomiais de 1º grau em representações geométricas no plano cartesiano, distinguindo os casos nos quais o comportamento é proporcional, recorrendo ou não a softwares ou aplicativos de álgebra e geometria dinâmica.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 28", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 541"}'::jsonb),
('BNCC-2018','EM13MAT402','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Converter representações algébricas de funções polinomiais de 2º grau em representações geométricas no plano cartesiano, distinguindo os casos nos quais uma variável for diretamente proporcional ao quadrado da outra, recorrendo ou não a softwares ou aplicativos de álgebra e geometria dinâmica, entre outros materiais.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 29", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 541"}'::jsonb),
('BNCC-2018','EM13MAT403','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Analisar e estabelecer relações, com ou sem apoio de tecnologias digitais, entre as representações de funções exponencial e logarítmica expressas em tabelas e em plano cartesiano, para identificar as características fundamentais (domínio, imagem, crescimento) de cada função.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 30", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 541"}'::jsonb),
('BNCC-2018','EM13MAT404','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Analisar funções definidas por uma ou mais sentenças (tabela do Imposto de Renda, contas de luz, água, gás etc.), em suas representações algébrica e gráfica, identificando domínios de validade, imagem, crescimento e decrescimento, e convertendo essas representações de uma para outra, com ou sem apoio de tecnologias digitais.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 31", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 541"}'::jsonb),
('BNCC-2018','EM13MAT405','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Utilizar conceitos iniciais de uma linguagem de programação na implementação de algoritmos escritos em linguagem corrente e/ou matemática.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 32", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 541"}'::jsonb),
('BNCC-2018','EM13MAT406','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Construir e interpretar tabelas e gráficos de frequências com base em dados obtidos em pesquisas por amostras estatísticas, incluindo ou não o uso de softwares que inter-relacionem estatística, geometria e álgebra.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 33", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 541"}'::jsonb),
('BNCC-2018','EM13MAT407','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Interpretar e comparar conjuntos de dados estatísticos por meio de diferentes diagramas e gráficos (histograma, de caixa (box-plot), de ramos e folhas, entre outros), reconhecendo os mais eficientes para sua análise.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 34", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 541"}'::jsonb),
('BNCC-2018','EM13MAT501','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Investigar relações entre números expressos em tabelas para representá-los no plano cartesiano, identificando padrões e criando conjecturas para generalizar e expressar algebricamente essa generalização, reconhecendo quando essa representação é de função polinomial de 1º grau.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 35", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 543"}'::jsonb),
('BNCC-2018','EM13MAT502','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Investigar relações entre números expressos em tabelas para representá-los no plano cartesiano, identificando padrões e criando conjecturas para generalizar e expressar algebricamente essa generalização, reconhecendo quando essa representação é de função polinomial de 2º grau do tipo y = ax2.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 36", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 543"}'::jsonb),
('BNCC-2018','EM13MAT503','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Investigar pontos de máximo ou de mínimo de funções quadráticas em contextos envolvendo superfícies, Matemática Financeira ou Cinemática, entre outros, com apoio de tecnologias digitais.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 37", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 543"}'::jsonb),
('BNCC-2018','EM13MAT504','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Investigar processos de obtenção da medida do volume de prismas, pirâmides, cilindros e cones, incluindo o princípio de Cavalieri, para a obtenção das fórmulas de cálculo da medida do volume dessas figuras.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 38", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 543"}'::jsonb),
('BNCC-2018','EM13MAT505','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Resolver problemas sobre ladrilhamento do plano, com ou sem apoio de aplicativos de geometria dinâmica, para conjecturar a respeito dos tipos ou composição de polígonos que podem ser utilizados em ladrilhamento, generalizando padrões observados.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 39", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 543"}'::jsonb),
('BNCC-2018','EM13MAT506','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Representar graficamente a variação da área e do perímetro de um polígono regular quando os comprimentos de seus lados variam, analisando e classificando as funções envolvidas.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 40", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 543"}'::jsonb),
('BNCC-2018','EM13MAT507','Ensino Médio','Matemática','Ensino Médio (sem seriação)','Identificar e associar progressões aritméticas (PA) a funções afins de domínios discretos, para análise de propriedades, dedução de algumas fórmulas e resolução de problemas.','{"documento": "bncc-2018", "arquivo": "BNCC_Ensino_Medio.xlsx", "proveniencia": "exportada de downloadbncc.mec.gov.br em 23/06/2023", "localizador": "aba ''Hab. de Matemática e suas Tec'', linha 41", "localizador_pdf": "Base-Nacional-Comum-Curricular-BNCC.pdf, página PDF 543"}'::jsonb),
